css:
.intelops-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f0c29 0%, #1a1a3e 50%, #24243e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e0e0;
}

.intelops-sim-header {
    background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 50%, #1a4a72 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 30px;
    box-shadow: 0 8px 32px rgba(0,100,200,0.3);
    text-align: center;
    border: 1px solid rgba(100,180,255,0.2);
}

.intelops-sim-header h1 {
    font-size: 1.8rem;
    margin-bottom: 5px;
}

.intelops-sim-header p {
    font-size: 1rem;
    opacity: 0.85;
    margin-bottom: 0;
}

.intelops-sim-period-counter {
    text-align: center;
    font-size: 1.2rem;
    margin-bottom: 25px;
    color: #90caf9;
}

.intelops-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.intelops-sim-status-card {
    background: rgba(255,255,255,0.06);
    border-radius: 15px;
    padding: 25px 20px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
    transition: transform 0.3s ease;
    text-align: center;
    border: 1px solid rgba(100,180,255,0.15);
    backdrop-filter: blur(10px);
}

.intelops-sim-status-card:hover {
    transform: translateY(-5px);
    border-color: rgba(100,180,255,0.4);
}

.intelops-sim-label {
    color: #90caf9;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
}

.intelops-sim-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #ffffff;
}

.intelops-sim-briefing {
    background: rgba(255,255,255,0.05);
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 25px;
    border-left: 4px solid #42a5f5;
}

.intelops-sim-briefing h3 {
    color: #64b5f6;
    margin-bottom: 15px;
    font-size: 1.2rem;
}

.intelops-sim-briefing-text {
    line-height: 1.7;
    color: #ccc;
    font-size: 0.95rem;
}

.intelops-sim-controls {
    background: rgba(255,255,255,0.05);
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 25px;
    border: 1px solid rgba(100,180,255,0.1);
}

.intelops-sim-controls h4 {
    color: #90caf9;
    margin-bottom: 10px;
}

.intelops-sim-help {
    color: #aaa;
    font-size: 0.9rem;
    margin-bottom: 20px;
}

.intelops-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 15px;
}

.intelops-sim-input-group {
    display: flex;
    flex-direction: column;
}

.intelops-sim-input-group label {
    font-size: 0.85rem;
    color: #90caf9;
    margin-bottom: 5px;
}

.intelops-sim-input-group .form-control {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(100,180,255,0.2);
    color: #fff;
    border-radius: 8px;
    padding: 8px 12px;
}

.intelops-sim-input-group .form-control:focus {
    border-color: #42a5f5;
    box-shadow: 0 0 8px rgba(66,165,245,0.3);
    background: rgba(255,255,255,0.12);
}

.intelops-sim-allocation-total {
    margin-top: 15px;
    text-align: right;
    font-size: 1.1rem;
    color: #64b5f6;
    font-weight: 600;
}

.intelops-sim-signal-cards {
    margin-bottom: 20px;
    max-height: 300px;
    overflow-y: auto;
    padding: 10px;
    background: rgba(0,0,0,0.2);
    border-radius: 10px;
}

.intelops-sim-signal-card {
    background: rgba(255,255,255,0.05);
    border-radius: 8px;
    padding: 12px;
    margin-bottom: 8px;
    border-left: 3px solid #ff9800;
    font-size: 0.88rem;
}

.intelops-sim-signal-card .signal-source {
    color: #ff9800;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
}

.intelops-sim-signal-card .signal-content {
    color: #ddd;
    margin-top: 4px;
}

.intelops-sim-signal-card .signal-reliability {
    color: #aaa;
    font-size: 0.78rem;
    margin-top: 4px;
}

.intelops-sim-wargame-brief {
    background: rgba(244,67,54,0.1);
    border: 1px solid rgba(244,67,54,0.3);
    border-radius: 10px;
    padding: 15px;
    margin-bottom: 20px;
    color: #ef9a9a;
    font-size: 0.95rem;
}

.intelops-sim-actions {
    text-align: center;
    margin-bottom: 30px;
}

.intelops-sim-actions .btn-primary {
    background: linear-gradient(135deg, #1e88e5, #1565c0);
    border: none;
    padding: 12px 40px;
    font-size: 1.1rem;
    border-radius: 10px;
    margin-right: 10px;
}

.intelops-sim-actions .btn-primary:hover {
    background: linear-gradient(135deg, #2196f3, #1976d2);
    box-shadow: 0 4px 15px rgba(33,150,243,0.4);
}

.intelops-sim-history {
    margin-bottom: 30px;
}

.intelops-sim-history .table {
    color: #e0e0e0;
    background: rgba(255,255,255,0.03);
}

.intelops-sim-history .table th {
    border-color: rgba(100,180,255,0.2);
    color: #90caf9;
}

.intelops-sim-history .table td {
    border-color: rgba(255,255,255,0.05);
}

.intelops-sim-chart {
    background: rgba(255,255,255,0.03);
    border-radius: 15px;
    padding: 20px;
    min-height: 300px;
}

@media (max-width: 768px) {
    .intelops-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .intelops-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .intelops-sim-header h1 {
        font-size: 1.3rem;
    }
}

