            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var maxPossible = scores.length * 25;
            var pct = Math.round((totalScore / maxPossible) * 100);

            var performance = 'Beginner Analyst';
            if (pct >= 85) performance = 'Master Strategist';
            else if (pct >= 70) performance = 'Senior Intelligence Officer';
            else if (pct >= 55) performance = 'Competent Analyst';
            else if (pct >= 40) performance = 'Junior Analyst';

            var insights = [];
            if (scores.length >= 1 && scores[0] >= 20) insights.push(window.mySimulation.t('insight_1'));
            if (scores.length >= 1 && scores[0] < 12) insights.push(window.mySimulation.t('insight_2'));
            if (scores.length >= 2 && scores[1] >= 20) insights.push(window.mySimulation.t('insight_3'));
            if (scores.length >= 2 && scores[1] < 12) insights.push(window.mySimulation.t('insight_4'));
            if (scores.length >= 3 && scores[2] >= 20) insights.push(window.mySimulation.t('insight_5'));
            if (scores.length >= 3 && scores[2] < 12) insights.push(window.mySimulation.t('insight_6'));
            if (scores.length >= 4 && scores[3] >= 20) insights.push(window.mySimulation.t('insight_7'));
            if (scores.length >= 4 && scores[3] < 12) insights.push(window.mySimulation.t('insight_8'));

            return {
                overallScore: pct,
                score: pct,
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: pct,
                performance: this._ratingLabel(performance),
                insights: insights
            };
        }

        _ratingLabel(name) {
            var map = { 'Master Strategist': 'rating_master', 'Senior Intelligence Officer': 'rating_senior', 'Competent Analyst': 'rating_competent', 'Junior Analyst': 'rating_junior', 'Beginner Analyst': 'rating_beginner' };
            return window.mySimulation.t(map[name] || 'rating_beginner');
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.pctScore >= 80) return window.mySimulation.t('hint_excellent');
            if (results.pctScore >= 50) return window.mySimulation.t('hint_good');
            return window.mySimulation.t('hint_improve');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score', formatter: (v) => v + ' / 25' },
                { key: 'results.pctScore', label: 'Percentage', i18nKey: 'col_pct', formatter: (v) => v + '%' },
                { key: 'results.totalScore', label: 'Cumulative', i18nKey: 'col_cumulative' },
                { key: 'results.feedback', label: 'Feedback', i18nKey: 'col_feedback' }
            ];
        }

